insert into sorting_item_translation (item_id, language_code, name, instruction) values (@id, 'fr', 'Vaisselle et sacs compostables ou biodegradables', 'Au bac noir, malgre leur nom. Ils se decomposent en petits fragments qui contaminent le plastique recyclable, et ils ne se degradent pas assez vite pour le bac brun.'), (@id, 'en', 'Compostable or biodegradable dishes and bags', 'In the black bin, despite the name. They break into small fragments that contaminate recyclable plastic, and they do not break down fast enough for the brown bin.'), (@id, 'zh', '可堆肥或可降解餐具和塑料袋', '尽管名字如此，仍放入黑桶。它们会碎成小颗粒污染可回收塑料，而分解速度又达不到棕桶的要求。');
