insert into sorting_item (destination_type, bin_color, source_url) values ('garbage', 'black', 'https://blainville.ca/services/environnement-et-voirie/ordures-menageres');
insert into sorting_item_translation (item_id, language_code, name, instruction) values (@id, 'fr', 'Essuie-tout souille de produits chimiques', 'Au bac noir. Le meme essuie-tout va au bac brun s''il n''a servi qu''a de la nourriture.'), (@id, 'en', 'Paper towel with chemicals on it', 'In the black bin. The same paper towel goes in the brown bin if it only touched food.'), (@id, 'zh', '沾过化学品的厨房纸', '放入黑桶。同样的厨房纸，如果只沾过食物，则应放入棕桶。');
