insert into sorting_item_translation (item_id, language_code, name, instruction) values (@id, 'fr', 'Vaisselle cassee', 'La vaisselle cassee va au bac noir. Les morceaux de vitre ou de miroir casses vont plutot a la collecte d''encombrants.'), (@id, 'en', 'Broken dishes', 'Broken dishes go in the black bin. Broken glass or mirror pieces go to the bulky collection instead.'), (@id, 'zh', '破碎餐具', '破碎餐具放入黑桶；碎玻璃和碎镜子则属于大件垃圾收集。');
