insert into sorting_item_translation (item_id, language_code, name, instruction) values (@id, 'fr', 'Plastique sans symbole', 'Au bac noir si ce n''est ni un contenant ni un emballage. Le bac bleu accepte les contenants, les emballages et les imprimes, c''est tout.'), (@id, 'en', 'Plastic with no recycling symbol', 'In the black bin if it is neither a container nor packaging. The blue bin takes containers, packaging and printed paper, and nothing else.'), (@id, 'zh', '无回收标志的塑料', '若既不是容器也不是包装，放入黑桶。蓝桶只收容器、包装和印刷品，仅此三类。');
